import sys, zipfile, re
import xml.etree.ElementTree as ET

MAIN = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
ET.register_namespace('', MAIN)

def col_letter(idx):
    s = ''
    while idx > 0:
        idx, rem = divmod(idx - 1, 26)
        s = chr(65 + rem) + s
    return s

def col_index(letter):
    n = 0
    for ch in (letter or '').upper():
        n = n * 26 + (ord(ch) - 64)
    return n

def cell_col(r):
    m = re.match(r'([A-Za-z]+)', r or '')
    return col_index(m.group(1)) if m else None

def cell_row(r):
    m = re.search(r'(\d+)$', r or '')
    return int(m.group(1)) if m else None

def cell_text(c):
    t = c.get('t')
    if t == 'inlineStr':
        is_el = c.find(f'{{{MAIN}}}is')
        if is_el is not None:
            return ''.join(x.text or '' for x in is_el.iter(f'{{{MAIN}}}t'))
        return ''
    return (c.text or '').strip()

path = sys.argv[1]
zin = zipfile.ZipFile(path)
parts = {i.filename: i for i in zin.infolist()}
data = {n: zin.read(n) for n in parts}
zin.close()

wb_xml = ET.fromstring(data['xl/workbook.xml'])
rels_xml = ET.fromstring(data['xl/_rels/workbook.xml.rels'])
rid2target = {}
for rel in rels_xml:
    if rel.tag == f'{{{REL}}}Relationship':
        rid2target[rel.get('Id')] = rel.get('Target')
sheet_target = None
sheet_name = None
for sh in wb_xml.iter(f'{{{MAIN}}}sheet'):
    sheet_name = sh.get('name')
    tgt = rid2target.get(sh.get(f'{{{REL}}}id'), '')
    if not tgt.startswith('/'):
        tgt = 'xl/' + tgt
    sheet_target = tgt.lstrip('/')
    break
print('Sheet:', sheet_name, '->', sheet_target)

sst = []
if 'xl/sharedStrings.xml' in data:
    ss = ET.fromstring(data['xl/sharedStrings.xml'])
    for si in ss.iter(f'{{{MAIN}}}si'):
        sst.append(''.join(t.text or '' for t in si.iter(f'{{{MAIN}}}t')))

sheet_xml = ET.fromstring(data[sheet_target])
sheet_data = sheet_xml.find(f'{{{MAIN}}}sheetData')

def get_val(c):
    if c.get('t') == 's':
        try:
            return sst[int(c.text)]
        except Exception:
            return ''
    return cell_text(c)

rows = sheet_data.findall(f'{{{MAIN}}}row')
headers = {}
if rows:
    for i, c in enumerate(rows[0].findall(f'{{{MAIN}}}c')):
        idx = cell_col(c.get('r')) or (i + 1)
        headers[idx] = get_val(c)
print('Headers:', {col_letter(k): v for k, v in headers.items()})

rev_idx = profit_idx = cost_idx = None
for idx, name in headers.items():
    low = str(name).lower()
    if 'margin' in low:
        continue
    if rev_idx is None and ('revenue' in low or 'sales' in low):
        rev_idx = idx
    if profit_idx is None and 'profit' in low:
        profit_idx = idx
    if cost_idx is None and low in ('cost', 'cogs', 'cost of goods sold'):
        cost_idx = idx

mode = None
if profit_idx and rev_idx:
    mode = 'profit/revenue'
elif rev_idx and cost_idx:
    mode = '(revenue-cost)/revenue'
else:
    idxs = sorted(headers)
    if len(idxs) >= 2:
        rev_idx, profit_idx = idxs[-2], idxs[-1]
        mode = 'last-two-columns fallback'
    else:
        raise SystemExit('cannot determine profit/revenue columns')
print('Mode:', mode, '| rev col:', rev_idx, '| profit col:', profit_idx, '| cost col:', cost_idx)

new_idx = None
for idx, name in headers.items():
    if 'profit margin' in str(name).lower():
        new_idx = idx
        break
if new_idx is None:
    maxcol = 1
    for row in rows:
        for c in row.findall(f'{{{MAIN}}}c'):
            ci = cell_col(c.get('r'))
            if ci:
                maxcol = max(maxcol, ci)
    new_idx = maxcol + 1
new_col = col_letter(new_idx)
print('New column:', new_col)

style_id = None
styles_path = 'xl/styles.xml'
if styles_path in data:
    try:
        st = ET.fromstring(data[styles_path])
        cell_xfs = st.find(f'{{{MAIN}}}cellXfs')
        if cell_xfs is not None:
            used = set()
            for nf in st.iter(f'{{{MAIN}}}numFmt'):
                try:
                    used.add(int(nf.get('numFmtId')))
                except Exception:
                    pass
            nfid = 165
            while nfid in used:
                nfid += 1
            num_fmts = st.find(f'{{{MAIN}}}numFmts')
            if num_fmts is None:
                num_fmts = ET.Element(f'{{{MAIN}}}numFmts')
                st.insert(0, num_fmts)
            ET.SubElement(num_fmts, f'{{{MAIN}}}numFmt',
                          {'numFmtId': str(nfid), 'formatCode': '0.0%'})
            num_fmts.set('count', str(len(num_fmts.findall(f'{{{MAIN}}}numFmt'))))
            style_id = len(cell_xfs.findall(f'{{{MAIN}}}xf'))
            ET.SubElement(cell_xfs, f'{{{MAIN}}}xf',
                          {'numFmtId': str(nfid), 'fontId': '0', 'fillId': '0',
                           'borderId': '0', 'xfId': '0', 'applyNumberFormat': '1'})
            cell_xfs.set('count', str(len(cell_xfs.findall(f'{{{MAIN}}}xf'))))
            data[styles_path] = ET.tostring(st, encoding='UTF-8', xml_declaration=True)
    except Exception as e:
        print('Style formatting skipped:', e)

max_row = 0
for row in rows:
    r = cell_row(row.get('r'))
    if r is None:
        continue
    max_row = max(max_row, r)
    cells = row.findall(f'{{{MAIN}}}c')
    if not cells:
        continue
    ref = f'{new_col}{r}'
    existing = next((c for c in cells if c.get('r') == ref), None)
    if r == 1:
        if existing is None:
            c = ET.SubElement(row, f'{{{MAIN}}}c', {'r': ref, 't': 'inlineStr'})
            is_el = ET.SubElement(c, f'{{{MAIN}}}is')
            t_el = ET.SubElement(is_el, f'{{{MAIN}}}t')
            t_el.text = 'Profit Margin %'
    else:
        if mode == '(revenue-cost)/revenue':
            formula = f'IFERROR(({col_letter(rev_idx)}{r}-{col_letter(cost_idx)}{r})/{col_letter(rev_idx)}{r},"")'
        else:
            formula = f'IFERROR({col_letter(profit_idx)}{r}/{col_letter(rev_idx)}{r},"")'
        if existing is not None:
            for ch in list(existing):
                existing.remove(ch)
            existing.set('t', '')
            f_el = ET.SubElement(existing, f'{{{MAIN}}}f')
            f_el.text = formula
            if style_id is not None:
                existing.set('s', str(style_id))
        else:
            c = ET.SubElement(row, f'{{{MAIN}}}c', {'r': ref})
            if style_id is not None:
                c.set('s', str(style_id))
            f_el = ET.SubElement(c, f'{{{MAIN}}}f')
            f_el.text = formula

dim = sheet_xml.find(f'{{{MAIN}}}dimension')
if dim is not None:
    dim.set('ref', f'A1:{new_col}{max_row}')

data[sheet_target] = ET.tostring(sheet_xml, encoding='UTF-8', xml_declaration=True)

zout = zipfile.ZipFile(path, 'w', zipfile.ZIP_DEFLATED)
for info in parts.values():
    zout.writestr(info, data[info.filename])
zout.close()
print('Saved', path)

z = zipfile.ZipFile(path)
sx = ET.fromstring(z.read(sheet_target))
for row in sx.iter(f'{{{MAIN}}}row'):
    r = cell_row(row.get('r'))
    if r and r <= 6:
        vals = []
        for c in row.findall(f'{{{MAIN}}}c'):
            f = c.find(f'{{{MAIN}}}f')
            vals.append((c.get('r'), f.text if f is not None else get_val(c)))
        print('row', r, vals)
z.close()

