                    pass
            nfid = 165
            while nfid in used:
                nfid += 1
            num_fmts = st.find(f'{{{MAIN}}}numFmts')
            if num_fmts is None:
                num_fmts = ET.Element(f'{{{MAIN}}}numFmts')
                st.insert(0, num_fmts)
