            cell_xfs.set('count', str(len(cell_xfs.findall(f'{{{MAIN}}}xf'))))
            data[styles_path] = ET.tostring(st, encoding='UTF-8', xml_declaration=True)
    except Exception as e:
        print('Style formatting skipped:', e)

max_row = 0
